interface RateLimiterAlgorithm {
    boolean tryConsume();
}

class TokenBucket implements RateLimiterAlgorithm {
    private final int maxTokens;
    private final double refillRate;    // tokens per second
    private double currentTokens;
    private long lastRefillNanos;

    public TokenBucket(int maxTokens, double refillRate) {
        this.maxTokens = maxTokens;
        this.refillRate = refillRate;
        this.currentTokens = maxTokens; // start full
        this.lastRefillNanos = System.nanoTime();
    }

    @Override
    public synchronized boolean tryConsume() {
        refill();
        if (currentTokens >= 1.0) {
            currentTokens -= 1.0;
            return true;
        }
        return false;
    }

    private void refill() {
        long now = System.nanoTime();
        long elapsedNanos = now - lastRefillNanos;
        if (elapsedNanos <= 0) return; // clock safety

        double elapsedSeconds = elapsedNanos / 1_000_000_000.0;
        double tokensToAdd = elapsedSeconds * refillRate;
        currentTokens = Math.min(maxTokens, currentTokens + tokensToAdd);
        lastRefillNanos = now;
    }
}

class SlidingWindowLog implements RateLimiterAlgorithm {
    private final long windowMillis;
    private final int maxRequests;
    private final Deque<Long> timestamps = new ArrayDeque<>();

    public SlidingWindowLog(int maxRequests, long windowSeconds) {
        this.maxRequests = maxRequests;
        this.windowMillis = windowSeconds * 1000;
    }

    @Override
    public synchronized boolean tryConsume() {
        long now = System.currentTimeMillis();
        long cutoff = now - windowMillis;

        // Evict stale entries from the front
        while (!timestamps.isEmpty() && timestamps.peekFirst() <= cutoff) {
            timestamps.pollFirst();
        }

        if (timestamps.size() < maxRequests) {
            timestamps.addLast(now);
            return true;
        }
        return false;
    }
}

class RateLimiter {
    private final ConcurrentHashMap<String, RateLimiterAlgorithm> buckets
        = new ConcurrentHashMap<>();
    private final Map<String, RateLimitConfig> configs
        = new ConcurrentHashMap<>();
    private final RateLimitConfig defaultConfig;

    public RateLimiter(RateLimitConfig defaultConfig) {
        this.defaultConfig = defaultConfig;
    }

    public boolean allowRequest(String clientId) {
        if (clientId == null || clientId.isBlank())
            throw new IllegalArgumentException("clientId required");

        RateLimiterAlgorithm algo = buckets.computeIfAbsent(
            clientId, id -> createAlgorithm(
                configs.getOrDefault(id, defaultConfig)));
        return algo.tryConsume();
    }

    public void registerClient(String clientId, RateLimitConfig config) {
        configs.put(clientId, config);
        buckets.remove(clientId); // force re-creation with new config
    }

    public void removeClient(String clientId) {
        configs.remove(clientId);
        buckets.remove(clientId);
    }

    private RateLimiterAlgorithm createAlgorithm(RateLimitConfig config) {
        return switch (config.algorithm()) {
            case TOKEN_BUCKET -> new TokenBucket(
                config.capacity(), config.refillRate());
            case SLIDING_WINDOW -> new SlidingWindowLog(
                config.capacity(), config.windowSeconds());
        };
    }

    // Optional: evict inactive clients to prevent memory leak
    public void evictInactive(Duration maxIdle) {
        // In production: track lastAccessed per bucket,
        // remove entries idle beyond maxIdle.
        // Or use Caffeine cache with expireAfterAccess.
    }
}
